@tool
extends Node

func _walk(base: String, out: Array) -> void:
	var d := DirAccess.open("res://" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if n.begins_with(".godot") == false and n != "__MACOSX":
			var p := (base + "/" + n) if base != "" else n
			if d.current_is_dir():
				_walk(p, out)
			else:
				out.append(p)
		n = d.get_next()
	d.list_dir_end()

func _qwalk(root: String, base: String, out: Array) -> void:
	var d := DirAccess.open(root if base == "" else root + "/" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if n.begins_with(".") == false:
			var p := (base + "/" + n) if base != "" else n
			if d.current_is_dir():
				_qwalk(root, p, out)
			else:
				out.append(root + "/" + p)
		n = d.get_next()
	d.list_dir_end()

func run() -> String:
	var files: Array = []
	_walk("", files)
	var d := DirAccess.open("res://")
	var removed := 0
	var fails: Array = []
	var sample: Array = []
	for f in files:
		var fs := String(f)
		var fn := fs.get_file()
		if fn.begins_with("._") or fn == ".DS_Store":
			var err := d.remove(fs)
			if err == OK:
				removed += 1
				if sample.size() < 10:
					sample.append(fs)
			else:
				fails.append(fs)
	var bin_hits: Array = []
	var proj: Array = []
	_walk("", proj)
	for f in proj:
		if String(f).contains("Decal_Line_90"):
			bin_hits.append("res://" + String(f))
	var q2: Array = []
	_qwalk("E:/ghost-company-quarantine", "", q2)
	for f in q2:
		if String(f).contains("Decal_Line_90"):
			bin_hits.append(String(f))
	var rep := {"junk_removed": removed, "failures": fails, "samples": sample, "decal_hits": bin_hits}
	var out := FileAccess.open("res://tools/gc_junk_report.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "JUNK removed=" + str(removed) + " fails=" + str(fails.size()) + " decal_hits=" + str(bin_hits.size())
